import {termPrincipal,termPayout,canUseTermDeposits} from './term-deposit.js';
export function renderTermDeposits(s,{won,escape:e,date}){const list=s.termDeposits?.contracts||[],active=list.filter(c=>c.status==='active');return `<details class="finance-help"><summary>계약형 예금 · 만기와 중도해지</summary><p>교육용 고정금리 계약입니다. 실제 당시 은행상품이 아니며 기존 변동금리 예금잔액과 별도입니다.</p><p>계약에 묶인 원금 <b>${won(termPrincipal(s))}</b> · 진행 ${active.length}건. 순자산에는 원금만 포함하고 미지급 이자는 제외합니다.</p><button class="btn secondary small" data-term-open="yes" ${!canUseTermDeposits(s)?'disabled':''}>계약 조건 확인</button>${!s.interestTax?'<p>이자 공제를 먼저 연결해 주세요.</p>':''}<div class="credit-contracts">${active.map(c=>`<article class="credit-contract"><h4>${e(c.id)} · ${won(c.amount)}</h4><p>${date(c.month)} → ${date(c.maturity)}<br>연 ${(c.rateBP/100).toFixed(2)}% 고정 · ${c.term}개월<br>현재 중도해지 실수령 ${won(termPayout(s,c).payout)}</p><button class="btn secondary small" data-term-close="${e(c.id)}" ${s.ended||s.pending?'disabled':''}>중도해지 결과 확인</button></article>`).join('')||'<p>진행 중인 계약이 없습니다.</p>'}</div>${list.some(c=>c.settlement)?`<details><summary>정산한 계약 기록</summary>${list.filter(c=>c.settlement).slice(-8).map(c=>`<p>${e(c.id)} · ${c.status==='matured'?'만기 수령':'중도해지'} · ${date(c.settlement.month)}<br>원금 ${won(c.amount)} · 세후 이자 ${won(c.settlement.net)}</p>`).join('')}<p>전체 정산은 삶의 장부와 영수증에 남습니다.</p></details>`:''}<p>가입 시 모형 금리를 연 0.01%p 단위로 고정합니다. 이자는 월 단위 단리로 계산해 만기에 원금과 함께 현금으로 지급합니다. 중도해지 연 금리는 0.1%와 계약 금리 중 낮은 값으로 고정하는 게임 규칙입니다. 3·6·12·24개월, 가입 100만원~1조원·진행 20건은 게임의 관리 범위입니다. 실제 상품 금액·기간·중도해지 금리로 주장하지 않습니다.</p><p>확정 후 금액·금리·기간은 수정할 수 없습니다. 부분 인출·추가 납입·자동 재예치·일별 이자·휴일 처리·상품별 세제는 미반영입니다. 미지급 이자는 월 수입이 아니며 만기 원금 반환은 소득이 아닙니다. 자동 만기 수령만 구현합니다.</p><a href="https://img2.kbstar.com/obj/ocommon/20210427_kbstar.pdf" target="_blank" rel="noopener noreferrer">은행 상품설명서 · 2021-03-24 기준 구조 참고 ↗</a></details>`;}
